import {
    type CommandExample,
    catchError,
    createHiddenDeprecatedTenantOption,
    extractErrorMessage,
    OutputFormatter,
    processContext,
    RESULTS,
} from "@uipath/common";
import type {
    ChoiceSetCreateOptions,
    ChoiceSetDeleteByIdOptions,
    ChoiceSetGetAllOptions,
    ChoiceSetGetByIdOptions,
    ChoiceSetServiceModel,
    ChoiceSetUpdateOptions,
    ChoiceSetValueDeleteOptions,
    ChoiceSetValueInsertOptions,
    ChoiceSetValueUpdateOptions,
} from "@uipath/uipath-typescript";
import { type Command, Option } from "commander";
import { fail, requireDestructiveConfirmation } from "../utils/output";
import { connectOrFail } from "../utils/sdk-client";

const OUTPUT_CODES = {
    ChoiceSetList: "ChoiceSetList",
    ChoiceSetValues: "ChoiceSetValues",
    ChoiceSetCreated: "ChoiceSetCreated",
    ChoiceSetUpdated: "ChoiceSetUpdated",
    ChoiceSetDeleted: "ChoiceSetDeleted",
    ChoiceSetValueCreated: "ChoiceSetValueCreated",
    ChoiceSetValueUpdated: "ChoiceSetValueUpdated",
    ChoiceSetValuesDeleted: "ChoiceSetValuesDeleted",
} as const;

interface ListOptions {
    tenant?: string;
    folderKey?: string;
    includeFolders?: boolean;
}

interface GetOptions {
    tenant?: string;
    limit?: string;
    offset?: string;
    cursor?: string;
    folderKey?: string;
}

interface CreateOptions {
    tenant?: string;
    displayName?: string;
    description?: string;
    folderKey?: string;
}

interface UpdateOptions {
    tenant?: string;
    displayName?: string;
    description?: string;
    folderKey?: string;
}

interface DeleteOptions {
    tenant?: string;
    yes?: boolean;
    confirm?: boolean;
    reason?: string;
    folderKey?: string;
}

interface ValueCreateOptions {
    tenant?: string;
    displayName?: string;
    folderKey?: string;
}

interface ValueUpdateOptions {
    tenant?: string;
    folderKey?: string;
}

interface ValueDeleteOptions {
    tenant?: string;
    ids?: string;
    yes?: boolean;
    confirm?: boolean;
    reason?: string;
    folderKey?: string;
}

